853	  if (!tab) return
854	  tab.pinned = pinned
855	  // 탭이 속한 워크스페이스를 재정렬해야 한다 — 인자 없으면 활성 ws 가 기본이라
856	  // 세션 복원 중 비활성 ws 의 핀 탭을 정렬 못 하고 활성 ws 만 헛되이 재정렬한다.
857	  reindex(tab.windowId, tab.workspaceId)
858	  emitTabList(tab.windowId)
859	}
860	
861	export function reorderTabs(windowId: string, orderedIds: string[]): void {
862	  orderedIds.forEach((id, i) => {
863	    const t = tabs.get(id)
864	    if (t && t.windowId === windowId) t.index = i
865	  })
866	  reindex(windowId, effectiveActiveWs(windowId))
867	  emitTabList(windowId)
868	}
869	
870	function reindex(windowId: string, workspaceId?: string): void {
871	  const wsId = workspaceId ?? effectiveActiveWs(windowId)
872	  const list = Array.from(tabs.values()).filter((t) => t.windowId === windowId && t.workspaceId === wsId)
873	  // 그룹 멤버는 인접하게 클러스터링 — 그룹의 rank = 멤버 중 최소 index, 그 위치에 모임
874	  const groupMin = new Map<string, number>()
875	  for (const t of list) {
876	    if (!t.groupId) continue
877	    const cur = groupMin.get(t.groupId)
878	    if (cur === undefined || t.index < cur) groupMin.set(t.groupId, t.index)
879	  }
880	  const rankOf = (t: TabRecord): number => (t.groupId != null ? (groupMin.get(t.groupId) ?? t.index) : t.index)
881	  list.sort((a, b) => {
882	    if (a.pinned !== b.pinned) return a.pinned ? -1 : 1
883	    const ra = rankOf(a)
884	    const rb = rankOf(b)
885	    if (ra !== rb) return ra - rb
886	    return a.index - b.index
887	  })
888	  list.forEach((t, i) => { t.index = i })
889	}

