async function main() {
  for (const f of ['save-deadlines.js', 'snapshot-schema.js']) {
    if (!fs.existsSync(path.join(DIST, f))) {
      console.error(`[session-schema] 컴파일 산출물이 없습니다: ${path.join(DIST, f)}\n`
